INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rayman Jungle Run', 'Rayman Jungle Run is powered by the same UbiArt Framework engine that brought you Rayman Origins. The legendary platforming hero is making the jump to your favorite mobile device. Rayman Jungle Run is easy for all ages to pick up and play, but challenging for the longtime Rayman fans to master. Unlock the Land of the Livid Dead levels if you have the skills!' FROM games WHERE igdb_id = 14533 ON CONFLICT (game_id, language_code) DO NOTHING;
