INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lisa: The First', 'Lisa: The First is a Yume-Nikki style exploration game. It was made in RPG Maker 2003 and released on October 9th, 2012. It is the predecessor to Lisa: The Painful. It is an exploration of Lisa Armstrong''s mind as she tries to cope with the burden of being abused by her father Marty before committing suicide.' FROM games WHERE igdb_id = 26652 ON CONFLICT (game_id, language_code) DO NOTHING;
