INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA Soccer 13', 'FIFA 13 captures the drama and unpredictability of real-world football. The game creates a true battle for possession across the entire pitch, delivers freedom and creativity in attack, and connects fans to the heartbeat of the sport - and to each other - through EA SPORTS Football Club. FIFA 13 features five breakthrough gameplay innovations which revolutionize artificial intelligence, dribbling, ball control and physical play, as well as engaging online features and live services. FIFA 13 with Kinect enables you to use voice commands to manage your club’s line-up and tactics without pausing the game, shout directions on the pitch in Be A Pro, and forces you to temper the way you talk to officials.' FROM games WHERE igdb_id = 2153 ON CONFLICT (game_id, language_code) DO NOTHING;
