INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xia-Xia', 'Explore it all in a fun carnival-like adventure with the fun and silly hermit crab characters in Xia-Xia the game. Set out on dozens of missions and along the way, meet kooky friends, and unlock loads of secret rewards in five unique worlds across 25 levels! Keep your eyes open, you must discover the hidden starfish in each world to move on to other adventures. With more than 30 collectible shells to uncover and over 60 missing friends to seek out, Xia-Xia the game provides hours of fun for all ages!' FROM games WHERE igdb_id = 9745 ON CONFLICT (game_id, language_code) DO NOTHING;
