INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SongPop: Classic', 'SongPop 1 is a head-to-head music trivia game. The free App was released in May 2012 by FreshPlanet, a venture-backed, NYC–based startup. It is available for iPhone, iPad, Android, and Facebook. By 2015, the app had been downloaded 100 million times. In July 2015, SongPop 2, featuring over 100,000 songs and 1,000 curated playlists, was released. SongPop 2 is free-to-play with in-app purchases. The game is played much like the popular TV show "Name That Tune." After selecting a themed playlist, five songs are played. Players compete against each other to be the first to select the correct song title or artist from a choice of four. iTune links are provided for each song.[5] In SongPop 2, users can play alone for the first time, competing against a computer-controlled opponent.' FROM games WHERE igdb_id = 23333 ON CONFLICT (game_id, language_code) DO NOTHING;
