INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Romance Dawn', 'The game is an RPG; it uses turn-based battles and action commands that help guide the player. The player commands the protagonist Luffy and other characters that are in his crew. The characters level up, and the player can strengthen attacks by obtaining points. All characters and enemies are from the One Piece series and play the same roles as seen in the source material. Cutscenes are told in a manga style.' FROM games WHERE igdb_id = 6851 ON CONFLICT (game_id, language_code) DO NOTHING;
