INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carmen Sandiego Adventures in Math: The Lady Liberty Larceny', 'Carmen Sandiego is back and only you can foil her V.I.L.E plans. Travel the globe, solve brain-twisting math puzzles, and catch the villain behind the Lady Liberty Larceny. Crack the case of the Lady Liberty Larceny in single-player Story Mode. Perfect your math skills in single-player Practice Mode. Challenge your friends and family to solve math puzzles against the clock in Multiplayer Mode. In Carmen Sandiego Adventures in Math: The Lady Liberty Larceny, you practice your math skills and use them to fight crime. Ideal for grades 4-5, math topics include geometry, logic puzzles, fractions and much more!' FROM games WHERE igdb_id = 51128 ON CONFLICT (game_id, language_code) DO NOTHING;
