INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choplifter HD', 'In Choplifter HD, players take on the role of an up-and-coming rescue pilot asked to join the elite, international helicopter rescue team. Pilots will be trained to command a variety of helicopters deployed on 30 different missions. Pilots must bank, hover, touch-down and sometimes even shake zombies from their chopper during lift-off in order to make their rescue and complete their mission. Command a variety of helicopters deployed on more than 30 different missions ranging from captured military prisoner extraction to saving survivors of viral outbreaks. Original Choplifter franchise creator Dan Gorlin serving as design consultant' FROM games WHERE igdb_id = 15158 ON CONFLICT (game_id, language_code) DO NOTHING;
