INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warsow', 'Warsow is set in a futuristic cartoonish world where rocketlauncher-wielding pigs and lasergun-carrying cyberpunks roam the streets. It is a completely free, fast-paced first-person shooter without hard graphical violence. Red stars instead of blood indicate hits and colored cubes replace guts as gib effects.' FROM games WHERE igdb_id = 11555 ON CONFLICT (game_id, language_code) DO NOTHING;
