INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mark of the Ninja', 'Mark of the Ninja is a side-scrolling action stealth video game developed by Klei Entertainment and published by Microsoft Studios. It was announced on February 28, 2012 and later released for the Xbox 360 via Xbox Live Arcade on September 7, 2012. A Microsoft Windows version was released on October 16, 2012. It follows the story of a nameless ninja in the present day, and features a themed conflict between ancient ninja tradition and modern technology. Cutscenes for the game are rendered in Saturday morning cartoon animation style.' FROM games WHERE igdb_id = 2129 ON CONFLICT (game_id, language_code) DO NOTHING;
